const root=document.querySelector('#commentItems'),message=document.querySelector('#commentMessage');let etag=null;
const escape=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function call(input){try{const r=await fetch('/api/comments',{method:input?'POST':'GET',headers:{'X-Chronicle-Request':'1','Content-Type':'application/json'},...(input?{body:JSON.stringify({...input,etag})}:{})});const data=await r.json();if(!r.ok)throw Error(data.error);etag=data.etag;render(data.items);message.textContent=input?'保存しました':'';}catch(e){message.textContent=e.message;}}
function render(items){root.innerHTML=items.filter(x=>x.status!=='deleted').map(x=>`<article data-comment="${escape(x.id)}"><p>${escape(({pending:'未承認',approved:'承認済み',rejected:'却下',spam:'スパム'})[x.status])}　${'コメント'}　${escape(x.name||'匿名')}</p><p class="comment-text">${escape(x.body)}</p><div>${(x.status==='approved'?['delete']:['approve','delete']).map(a=>`<button data-action="${a}">${a==='approve'?'承認':'削除'}</button>`).join('')}</div>${x.status==='approved'?`<label>返信 任意<textarea maxlength="4000">${escape(x.reply)}</textarea></label><button data-action="reply">返信を保存</button>`:''}</article>`).join('')||'<p>コメントはありません</p>';root.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>{const card=button.closest('article');call({action:button.dataset.action,id:card.dataset.comment,body:card.querySelector('textarea')?.value||''});});}
document.querySelector('#reloadComments').onclick=()=>call();const postId=new URLSearchParams(location.search).get('post');document.querySelector('#commentTest').hidden=!postId||postId.startsWith('sample-');document.querySelector('#commentTest').onsubmit=e=>{e.preventDefault();call({action:'submit',...Object.fromEntries(new FormData(e.target)),postId});};call();
